css:
/* Service comparison: what each service includes. One header row and one repeated row per task
   (`rows` prop); each cell reads "Included" or an em dash. */
.bz-section[data-bz-node="scmp"]{background:#e6e6e4;padding-block:clamp(56px,6vw,96px)}
[data-bz-node="scmp"] .bz-block{padding-block:0}
[data-bz-node="scmp-h"] h2{max-width:60rem;margin-bottom:var(--space-3)}
[data-bz-node="scmp-t"] .bz-text p{font-size:.875rem;line-height:1.85;color:#3d3c39;max-width:56rem;margin:0 0 var(--space-5)}
[data-bz-node="scmp-head"],[data-bz-node^="scmp-row"]{grid-template-columns:minmax(0,6fr) repeat(3,minmax(0,2fr));gap:0;background:#fff;border:1px solid var(--line);border-top:0}
[data-bz-node="scmp-head"]{border-top:1px solid var(--line);background:#151515}
[data-bz-node="scmp-head"]>.bz-col,[data-bz-node^="scmp-row"]>.bz-col{grid-column:auto;padding:14px 16px;display:flex;align-items:center}
[data-bz-node="scmp-head"] .bz-text p{font:700 .6875rem/1.4 var(--font-body)!important;letter-spacing:.1em;text-transform:uppercase;color:#fff!important;margin:0!important;text-align:center;width:100%}
[data-bz-node^="scmp-row"]>.bz-col+.bz-col{border-left:1px solid var(--line);justify-content:center}
[data-bz-node^="scmp-row"] .bz-text p{font-size:.8125rem!important;line-height:1.4;color:var(--ink)!important;margin:0!important}
[data-bz-node^="scmp-ct"] .bz-text p{font:700 .6875rem/1.3 var(--font-body)!important;letter-spacing:.08em;text-transform:uppercase;color:var(--accent-dark)!important;text-align:center}
[data-bz-node^="scmp-"] .bz-container{padding:0;max-width:none}
@media (max-width:640px){[data-bz-node="scmp-head"],[data-bz-node^="scmp-row"]{grid-template-columns:minmax(0,5fr) repeat(3,minmax(0,2fr))}[data-bz-node="scmp-head"]>.bz-col,[data-bz-node^="scmp-row"]>.bz-col{padding:10px 8px}[data-bz-node^="scmp-c"] .bz-text p,[data-bz-node="scmp-head"] .bz-text p{font-size:.5625rem!important;letter-spacing:.04em}}
